1	import Link from "next/link";
2	import { notFound } from "next/navigation";
3	import { db } from "@/lib/db";
4	import { requireArea } from "@/lib/rbac";
5	import { PageHeader, Badge, EmptyState, timeAgo } from "@/components/ui/primitives";
6	import { contactStatusBadge } from "@/lib/coldemail/leaddb";
7	
8	export const dynamic = "force-dynamic";
9	
10	const EVENT_TONE: Record<string, "green" | "red" | "amber" | "slate" | "brand"> = {
11	  SENT: "slate",
12	  DELIVERED: "green",
13	  OPEN: "slate",
14	  CLICK: "brand",
15	  REPLY: "green",
16	  POSITIVE_REPLY: "green",
17	  HARD_BOUNCE: "red",
18	  SOFT_BOUNCE: "amber",
19	  BOUNCE: "red",
20	  COMPLAINT: "red",
21	  UNSUBSCRIBE: "amber",
22	  FAILED: "red",
23	};
24	
25	function fmt(d: Date | null | undefined): string {
26	  return d ? new Date(d).toISOString().slice(0, 16).replace("T", " ") : "—";
27	}
28	
29	export default async function ContactDetail({ params }: { params: Promise<{ id: string }> }) {
30	  await requireArea("platform");
31	  const { id } = await params;
32	
33	  const contact = await db.contact.findUnique({
34	    where: { id },
35	    include: {
36	      business: true,
37	      importBatch: { select: { name: true, createdAt: true } },
38	      consentRecords: { orderBy: { createdAt: "desc" }, take: 3 },
39	      sends: {
40	        orderBy: { createdAt: "desc" },
41	        include: {
42	          campaign: { select: { id: true, name: true, brand: { select: { name: true } } } },
43	          inbox: { select: { email: true } },
44	          step: { select: { stepOrder: true } },
45	          events: { orderBy: { createdAt: "desc" } },
46	        },
47	      },
48	      conversations: {
49	        orderBy: { lastMessageAt: "desc" },
50	        include: {
51	          inbox: { select: { email: true } },
52	          messages: { orderBy: { createdAt: "asc" }, take: 20 },
53	        },
54	      },
55	    },
56	  });
57	  if (!contact) notFound();
58	
59	  const badge = contactStatusBadge(contact);
60	
61	  // Distinct campaigns this contact appeared in.
62	  const campaignMap = new Map<string, { name: string; brand: string }>();
63	  for (const s of contact.sends) {
64	    if (s.campaign) campaignMap.set(s.campaign.id, { name: s.campaign.name, brand: s.campaign.brand?.name ?? "" });
65	  }
66	
67	  // Build a flat, newest-first activity timeline from send events.
68	  type TL = { at: Date; type: string; campaign: string; inbox: string; meta: string };
69	  const timeline: TL[] = [];
70	  for (const s of contact.sends) {
71	    const camp = s.campaign?.name ?? "—";
72	    const inbox = s.inbox?.email ?? "(brand relay)";
73	    for (const e of s.events) {
74	      timeline.push({ at: e.createdAt, type: e.type, campaign: camp, inbox, meta: e.meta });
75	    }
76	  }
77	  timeline.sort((a, b) => b.at.getTime() - a.at.getTime());
78	
79	  return (
80	    <div className="space-y-6">
81	      <PageHeader
82	        title={contact.fullName || contact.email}
83	        sub={contact.title ? `${contact.title} · ${contact.business.name}` : contact.business.name}
84	      />
85	      <Link href="/admin/coldemail/businesses" className="text-xs text-brand-300 hover:underline">
86	        ← Back to businesses
87	      </Link>
88	
89	      {/* Identity + status */}
90	      <div className="card space-y-3">
91	        <div className="flex flex-wrap items-center gap-3">
92	          <Badge tone={badge.tone}>{badge.label}</Badge>
93	          <span className="text-sm text-slate-300">{contact.email}</span>
94	          <span className="text-xs text-slate-500">Stage: {contact.stage}</span>
95	          <span className="text-xs text-slate-500">Address health: {contact.emailStatus}</span>
96	        </div>
97	        {contact.deadAt && (
98	          <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-300">
99	            Dead since {fmt(contact.deadAt)} — {contact.deadReason || "no reason recorded"}. Excluded from all
100	            future campaigns.
101	          </div>
102	        )}
103	      </div>
104	
105	      {/* Engagement + health metrics */}
106	      <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6">
107	        <Metric label="Times emailed" value={String(contact.timesEmailed)} />
108	        <Metric label="First emailed" value={fmt(contact.firstEmailedAt)} />
109	        <Metric label="Last emailed" value={fmt(contact.lastEmailedAt)} />
110	        <Metric label="Replied" value={fmt(contact.repliedAt)} tone={contact.repliedAt ? "green" : "slate"} />
111	        <Metric label="Bounce count" value={String(contact.bounceCount)} tone={contact.bounceCount ? "red" : "slate"} />
112	        <Metric label="Last bounce" value={fmt(contact.lastBounceAt)} />
113	      </div>
114	
115	      {/* Campaigns */}
116	      <div className="card">
117	        <p className="section-label mb-3">Campaigns ({campaignMap.size})</p>
118	        {campaignMap.size === 0 ? (
119	          <p className="text-sm text-slate-500">Not part of any campaign yet.</p>
120	        ) : (
121	          <ul className="space-y-1 text-sm text-slate-300">
122	            {Array.from(campaignMap.values()).map((c, i) => (
123	              <li key={i}>
124	                {c.name}
125	                {c.brand && <span className="text-xs text-slate-500"> · {c.brand}</span>}
126	              </li>
127	            ))}
128	          </ul>
129	        )}
130	      </div>
131	
132	      {/* Sends (which mailbox sent each email) */}
133	      <div className="card overflow-x-auto p-0">
134	        <p className="section-label px-4 pt-4">Sends ({contact.sends.length})</p>
135	        {contact.sends.length === 0 ? (
136	          <div className="p-4">
137	            <EmptyState title="No sends" sub="This contact has not been sent anything yet." />
138	          </div>
139	        ) : (
140	          <table className="table-shell mt-2 min-w-[720px]">
141	            <thead>
142	              <tr>
143	                <th>Campaign</th>
144	                <th>Step</th>
145	                <th>Mailbox / inbox</th>
146	                <th>Status</th>
147	                <th>Sent</th>
148	              </tr>
149	            </thead>
150	            <tbody>
151	              {contact.sends.map((s) => (
152	                <tr key={s.id}>
153	                  <td className="align-top text-slate-200">{s.campaign?.name ?? "—"}</td>
154	                  <td className="align-top text-slate-400">{s.step ? `#${s.step.stepOrder + 1}` : "—"}</td>
155	                  <td className="align-top text-slate-400">{s.inbox?.email ?? "(brand relay)"}</td>
156	                  <td className="align-top text-slate-400">{s.status}</td>
157	                  <td className="align-top text-slate-500">{fmt(s.sentAt)}</td>
158	                </tr>
159	              ))}
160	            </tbody>
161	          </table>
162	        )}
163	      </div>
164	
165	      {/* Activity timeline */}
166	      <div className="card">
167	        <p className="section-label mb-3">Activity timeline ({timeline.length})</p>
168	        {timeline.length === 0 ? (
169	          <p className="text-sm text-slate-500">No open/click/reply/bounce events recorded.</p>
170	        ) : (
171	          <ul className="space-y-2">
172	            {timeline.slice(0, 60).map((t, i) => (
173	              <li key={i} className="flex flex-wrap items-center gap-2 text-sm">
174	                <Badge tone={EVENT_TONE[t.type] ?? "slate"}>{t.type.replace(/_/g, " ").toLowerCase()}</Badge>
175	                <span className="text-slate-400">{t.campaign}</span>
176	                <span className="text-xs text-slate-600">via {t.inbox}</span>
177	                <span className="ml-auto text-xs text-slate-500">{timeAgo(t.at)}</span>
178	              </li>
179	            ))}
180	          </ul>
181	        )}
182	      </div>
183	
184	      {/* Conversations */}
185	      {contact.conversations.length > 0 && (
186	        <div className="card space-y-4">
187	          <p className="section-label">Conversations ({contact.conversations.length})</p>
188	          {contact.conversations.map((c) => (
189	            <div key={c.id} className="rounded-lg border border-slate-700/60 p-3">
190	              <div className="flex items-center gap-2">
191	                <Badge tone="brand">{c.status}</Badge>
192	                <span className="text-sm text-slate-300">{c.subject || "(no subject)"}</span>
193	                <span className="ml-auto text-xs text-slate-500">{c.inbox.email}</span>
194	              </div>
195	              <ul className="mt-2 space-y-1 text-xs text-slate-400">
196	                {c.messages.map((m) => (
197	                  <li key={m.id}>
198	                    <span className={m.direction === "INBOUND" ? "text-emerald-300" : "text-slate-500"}>
199	                      {m.direction === "INBOUND" ? "← reply" : "→ sent"}
200	                    </span>{" "}
201	                    {(m.bodyText || "").replace(/\s+/g, " ").slice(0, 160) || "(no text)"}
202	                  </li>
203	                ))}
204	              </ul>
205	            </div>
206	          ))}
207	        </div>
208	      )}
209	    </div>
210	  );
211	}
212	
213	function Metric({ label, value, tone = "slate" }: { label: string; value: string; tone?: "slate" | "green" | "red" }) {
214	  const colors = { slate: "text-slate-200", green: "text-emerald-300", red: "text-red-300" };
215	  return (
216	    <div className="card p-3">
217	      <p className="text-[12px] text-slate-400">{label}</p>
218	      <p className={`mt-1 text-sm font-semibold ${colors[tone]}`}>{value}</p>
219	    </div>
220	  );
221	}
222

1	import Link from "next/link";
2	import { db } from "@/lib/db";
3	import { requireArea } from "@/lib/rbac";
4	import { PageHeader, Badge, EmptyState } from "@/components/ui/primitives";
5	import { summarizeLeadHealth, contactStatusBadge } from "@/lib/coldemail/leaddb";
6	import {
7	  ListCreateForm,
8	  AddContactToListForm,
9	  ListMemberRemove,
10	  ListDelete,
11	} from "@/components/admin/coldemail/Controls";
12	
13	export const dynamic = "force-dynamic";
14	
15	export default async function ColdEmailLists() {
16	  await requireArea("platform");
17	
18	  const [lists, brands, contacts] = await Promise.all([
19	    db.emailList.findMany({
20	      orderBy: { createdAt: "desc" },
21	      include: {
22	        brand: { select: { name: true } },
23	        members: {
24	          include: {
25	            contact: {
26	              select: { id: true, email: true, fullName: true, emailStatus: true, timesEmailed: true, repliedAt: true },
27	            },
28	          },
29	          orderBy: { createdAt: "asc" },
30	        },
31	      },
32	    }),
33	    db.brand.findMany({ orderBy: { createdAt: "asc" }, select: { id: true, name: true } }),
34	    db.contact.findMany({
35	      orderBy: { createdAt: "desc" },
36	      select: { id: true, email: true, fullName: true },
37	      take: 500,
38	    }),
39	  ]);
40	
41	  const brandOptions = brands.map((b) => ({ id: b.id, label: b.name }));
42	  const contactOptions = contacts.map((c) => ({
43	    id: c.id,
44	    label: c.fullName ? `${c.fullName} · ${c.email}` : c.email,
45	  }));
46	  const listOptions = lists.map((l) => ({ id: l.id, label: l.name }));
47	
48	  return (
49	    <div className="space-y-6">
50	      <PageHeader title="Lists" sub="Static lists of contacts, optionally scoped to a sending brand." />
51	
52	      <div className="grid gap-6 lg:grid-cols-2">
53	        <div className="card">
54	          <p className="section-label mb-4">Create a list</p>
55	          <ListCreateForm brands={brandOptions} />
56	        </div>
57	        <div className="card">
58	          <p className="section-label mb-4">Add a contact to a list</p>
59	          <AddContactToListForm lists={listOptions} contacts={contactOptions} />
60	        </div>
61	      </div>
62	
63	      {lists.length === 0 ? (
64	        <EmptyState title="No lists yet" sub="Create your first list above." />
65	      ) : (
66	        <div className="space-y-4">
67	          {lists.map((l) => {
68	            const health = summarizeLeadHealth(l.members.map((m) => m.contact));
69	            return (
70	              <div key={l.id} className="card">
71	                <div className="mb-3 flex flex-wrap items-start justify-between gap-3">
72	                  <div>
73	                    <div className="flex items-center gap-2">
74	                      <span className="font-medium text-white">{l.name}</span>
75	                      {l.brand && <Badge tone="brand">{l.brand.name}</Badge>}
76	                      <Badge tone="slate">{l.members.length} contacts</Badge>
77	                    </div>
78	                    {l.description && <p className="mt-1 text-xs text-slate-500">{l.description}</p>}
79	                  </div>
80	                  <ListDelete id={l.id} />
81	                </div>
82	
83	                {/* Lead-health rollup */}
84	                <div className="mb-3 flex flex-wrap gap-4 rounded-lg border border-slate-700/60 bg-slate-900/40 px-3 py-2 text-xs">
85	                  <span className="text-emerald-300">Sendable {health.sendable}</span>
86	                  <span className="text-red-300">Dead/bounced {health.dead}</span>
87	                  <span className="text-slate-300">Emailed {health.emailed}</span>
88	                  <span className="text-slate-300">Replied {health.replied}</span>
89	                </div>
90	
91	                {l.members.length === 0 ? (
92	                  <p className="text-sm text-slate-500">No contacts on this list yet.</p>
93	                ) : (
94	                  <ul className="divide-y divide-white/[0.06]">
95	                    {l.members.slice(0, 100).map((m) => {
96	                      const badge = contactStatusBadge(m.contact);
97	                      return (
98	                        <li key={m.id} className="flex items-center justify-between py-2">
99	                          <span className="flex items-center gap-2 text-sm text-slate-300">
100	                            <Badge tone={badge.tone}>{badge.label}</Badge>
101	                            <Link href={`/admin/coldemail/contacts/${m.contact.id}`} className="hover:text-brand-300">
102	                              {m.contact.fullName ? `${m.contact.fullName} · ` : ""}
103	                              <span className="text-slate-500">{m.contact.email}</span>
104	                            </Link>
105	                          </span>
106	                          <ListMemberRemove id={m.id} />
107	                        </li>
108	                      );
109	                    })}
110	                  </ul>
111	                )}
112	              </div>
113	            );
114	          })}
115	        </div>
116	      )}
117	    </div>
118	  );
119	}
