1	import { db } from "@/lib/db";
2	import { requireArea } from "@/lib/rbac";
3	import { getSetting } from "@/lib/settings";
4	import { PageHeader, Badge, EmptyState } from "@/components/ui/primitives";
5	import { BrandForm, BrandDelete, ClearBrandPauseButton } from "@/components/admin/coldemail/Controls";
6	import { BrandDnsVerify } from "@/components/admin/coldemail/DnsVerify";
7	import { evaluateSendEligibility, protectedDomainSet, normalizeDomain, emailDomain } from "@/lib/coldemail/compliance";
8	
9	export const dynamic = "force-dynamic";
10	
11	function appHost(): string | null {
12	  try {
13	    return process.env.APP_URL ? new URL(process.env.APP_URL).host : null;
14	  } catch {
15	    return null;
16	  }
17	}
18	
19	export default async function ColdEmailBrands() {
20	  await requireArea("platform");
