10	/** Compact planned-ramp bar chart; highlights the current warmup day. */
11	function RampChart({ startCap, targetCap, rampDays, currentDay }: { startCap: number; targetCap: number; rampDays: number; currentDay: number }) {
12	  const curve = warmupRampCurve({ startCap, targetCap, rampDays });
13	  const max = Math.max(1, targetCap);
14	  return (
15	    <div className="flex h-16 items-end gap-[2px]">
16	      {curve.map((p) => {
17	        const h = Math.max(6, Math.round((p.planned / max) * 100));
18	        const isNow = p.day === Math.min(currentDay, rampDays);
19	        return (
20	          <div
21	            key={p.day}
22	            title={`Day ${p.day + 1}: ${p.planned}/day`}
23	            style={{ height: `${h}%` }}
24	            className={`w-full rounded-sm ${isNow ? "bg-brand-400" : p.day < currentDay ? "bg-brand-500/70" : "bg-white/10"}`}
25	          />
26	        );
27	      })}
28	    </div>
29	  );
30	}
