15	async function actorEmails(logs: { detail: string | null }[]): Promise<Map<string, string>> {
16	  const ids = [...new Set(logs.map((l) => actingAdminId(l.detail)).filter(Boolean))] as string[];
17	  if (ids.length === 0) return new Map();
18	  const users = await db.user.findMany({ where: { id: { in: ids } }, select: { id: true, email: true } });
19	  return new Map(users.map((u) => [u.id, u.email]));
20	}
