142	type Activity = {
143	  id: string;
144	  at: Date;
145	  kind: "audit" | "payment" | "job";
146	  tone: "brand" | "green" | "amber" | "slate" | "red";
147	  label: string;
148	  text: string;
149	  actor?: string | null;
150	};
151	
152	async function ActivityTab() {
153	  const [audits, txns, jobs] = await Promise.all([
154	    db.auditLog.findMany({
155	      include: { user: { select: { email: true } } },
156	      orderBy: { createdAt: "desc" },
157	      take: 40,
158	    }),
159	    db.walletTransaction.findMany({
160	      include: { user: { select: { email: true } } },
161	      orderBy: { createdAt: "desc" },
162	      take: 40,
163	    }),
164	    db.job.findMany({ orderBy: { createdAt: "desc" }, take: 40 }),
165	  ]);
166	
167	  const items: Activity[] = [];
168	  const actors = await actorEmails(audits);
169	
170	  for (const a of audits) {
171	    // Same attribution rule as the Audit tab: an action taken while impersonating
172	    // belongs to the admin who took it, not to the account it was taken as.
173	    const asAdmin = actingAdminId(a.detail);
174	    items.push({
175	      id: `a-${a.id}`,
176	      at: a.createdAt,
177	      kind: "audit",
178	      tone: asAdmin || a.action.startsWith("admin.") ? "amber" : "brand",
179	      label: a.action,
180	      text: asAdmin ? detailWithoutActor(a.detail) : (a.detail ?? ""),
181	      actor: asAdmin
182	        ? `${actors.get(asAdmin) ?? asAdmin} — impersonating ${a.user?.email ?? "customer"}`
183	        : (a.user?.email ?? "system"),
184	    });
185	  }
186	  for (const t of txns) {
187	    const credit = t.amountCents >= 0;
188	    items.push({
189	      id: `t-${t.id}`,
190	      at: t.createdAt,
191	      kind: "payment",
192	      tone: credit ? "green" : "slate",
193	      label: credit ? "wallet.credit" : "wallet.debit",
194	      text: `${fmtMoney(t.amountCents)} · ${t.description}`,
195	      actor: t.user?.email ?? null,
196	    });
197	  }
198	  for (const j of jobs) {
199	    items.push({
200	      id: `j-${j.id}`,
201	      at: j.createdAt,
202	      kind: "job",
203	      tone: j.status === "FAILED" ? "red" : j.status === "DONE" ? "green" : "slate",
204	      label: `job.${String(j.type).toLowerCase()}`,
205	      text: `${j.status}${j.error ? ` · ${j.error}` : ""}`,
206	      actor: null,
207	    });
208	  }
209	
210	  items.sort((a, b) => b.at.getTime() - a.at.getTime());
211	  const feed = items.slice(0, 80);
212	
213	  return (
214	    <div className="card divide-y divide-white/[0.05] p-0">
215	      {feed.map((it) => (
216	        <div key={it.id} className="flex items-start gap-3 px-4 py-3">
217	          <Badge tone={it.tone}>{it.kind}</Badge>
218	          <div className="min-w-0 flex-1">
219	            <p className="text-sm">
220	              <code className="font-mono text-xs text-brand-300">{it.label}</code>
221	              {it.text && <span className="ml-2 text-slate-300">{it.text}</span>}
222	            </p>
223	            {it.actor && <p className="mt-0.5 text-xs text-slate-500">{it.actor}</p>}
224	          </div>
225	          <span className="whitespace-nowrap text-xs text-slate-500" title={it.at.toISOString()}>
226	            {timeAgo(it.at)}
227	          </span>
228	        </div>
229	      ))}
230	    </div>
231	  );
232	}
